import os
from typing import Any, Dict, Optional

import requests


class Auth0FederatedProfileFetcher:
    def __init__(self, domain: Optional[str] = None, access_token: Optional[str] = None, timeout: int = 15):
        self.domain = (domain or os.environ.get("AUTH0_DOMAIN", "")).strip()
        self.access_token = (access_token or os.environ.get("AUTH0_ACCESS_TOKEN", "")).strip()
        self.timeout = timeout
        if not self.domain:
            raise ValueError("Missing Auth0 domain. Set AUTH0_DOMAIN or pass domain.")
        if not self.access_token:
            raise ValueError("Missing Auth0 access token. Set AUTH0_ACCESS_TOKEN or pass access_token.")

    def fetch_user_profile(self, user_id: str) -> Dict[str, Any]:
        if not user_id:
            raise ValueError("user_id is required")

        url = f"https://{self.domain}/api/v2/users/{requests.utils.quote(user_id, safe='')}"
        headers = {
            "Authorization": f"Bearer {self.access_token}",
            "Accept": "application/json",
        }

        response = requests.get(url, headers=headers, timeout=self.timeout)
        response.raise_for_status()
        raw = response.json()
        return self._normalize_claims(raw)

    def _normalize_claims(self, raw: Dict[str, Any]) -> Dict[str, Any]:
        identities = raw.get("identities") or []
        primary_identity = identities[0] if identities else {}

        normalized = {
            "subject": raw.get("user_id"),
            "issuer": f"https://{self.domain}/",
            "provider": primary_identity.get("provider"),
            "connection": primary_identity.get("connection"),
            "federated_user_id": primary_identity.get("user_id"),
            "email": raw.get("email"),
            "email_verified": bool(raw.get("email_verified")) if raw.get("email_verified") is not None else None,
            "name": raw.get("name"),
            "given_name": raw.get("given_name"),
            "family_name": raw.get("family_name"),
            "nickname": raw.get("nickname"),
            "preferred_username": raw.get("nickname"),
            "picture": raw.get("picture"),
            "locale": raw.get("locale"),
            "updated_at": raw.get("updated_at"),
            "last_login": raw.get("last_login"),
            "login_count": raw.get("logins_count"),
            "blocked": raw.get("blocked"),
            "created_at": raw.get("created_at"),
            "raw_claims": raw,
        }

        user_metadata = raw.get("user_metadata") or {}
        app_metadata = raw.get("app_metadata") or {}

        if not normalized["given_name"] and user_metadata.get("given_name"):
            normalized["given_name"] = user_metadata.get("given_name")
        if not normalized["family_name"] and user_metadata.get("family_name"):
            normalized["family_name"] = user_metadata.get("family_name")
        if not normalized["locale"] and user_metadata.get("locale"):
            normalized["locale"] = user_metadata.get("locale")

        normalized["groups"] = app_metadata.get("groups") or user_metadata.get("groups") or []
        normalized["roles"] = app_metadata.get("roles") or []
        normalized["organization"] = app_metadata.get("organization") or user_metadata.get("organization")

        return normalized


def fetch_and_normalize_federated_profile(user_id: str) -> Dict[str, Any]:
    return Auth0FederatedProfileFetcher().fetch_user_profile(user_id)
